insert into questions (id, type, data, status) values ('q_mtf_migraine_prophylaxis_001', 'MTF', '{"dateAdded":"2026-10-16","rotationIndex":160,"stem":"Regarding migraine prophylaxis:","choices":["Beta-blockers can be used","Angiotensin receptor blockers can be used","Sodium valproate is a routine option for women","Triptans taken daily are an effective option","Tricyclic antidepressants can be used"],"correct":[true,true,false,false,true],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Prophylaxis is considered when attacks are frequent or disabling. First-line options include beta-blockers, tricyclic antidepressants and ACE inhibitors or angiotensin receptor blockers; topiramate and sodium valproate are second line, and CGRP monoclonal antibodies third line.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. TRUE</strong> &mdash; Beta-blockers such as propranolol are established first-line prophylactic agents.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. TRUE</strong> &mdash; Angiotensin receptor blockers (and ACE inhibitors) are recognised first-line prophylactic options.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. FALSE</strong> &mdash; Sodium valproate is teratogenic and women may be of childbearing potential, so it is not a routine option for women. MHRA pregnancy prevention requirements apply (as for topiramate): avoid unless the conditions of the pregnancy prevention programme are met.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. FALSE</strong> &mdash; Triptans are acute abortive treatments. Frequent use risks medication-overuse headache; they are not used as daily prophylaxis.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. TRUE</strong> &mdash; Tricyclic antidepressants such as amitriptyline are used for prophylaxis, independent of any antidepressant effect.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Migraine</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\">\n    <div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Migraine is a primary headache disorder of recurrent attacks of moderate-to-severe, typically unilateral and pulsating headache with autonomic and sensory features (nausea, photophobia, phonophobia), in some patients preceded or accompanied by transient, fully reversible neurological symptoms (aura). It is thought to arise from neuronal hyperexcitability (cortical spreading depression, particularly relevant to aura) and activation of the trigeminovascular system, with release of vasoactive neuropeptides (e.g. CGRP) and central sensitisation.</p></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Epidemiology and types</div><table style=\"margin:0\"><tr><th>Feature</th><th>Detail</th></tr><tr><td>Epidemiology</td><td>Incidence 8.1/1000; male:female ratio ~1:3; onset commonly in the 2nd&ndash;3rd decade; 70% have a positive family history</td></tr><tr><td>Types</td><td>Migraine without aura (70%) and migraine with aura (30%, &ldquo;classic migraine&rdquo;)</td></tr><tr><td>Episodic migraine</td><td>Headache on fewer than 15 days per month</td></tr><tr><td>Chronic migraine</td><td>Headache on &ge;15 days per month for &gt;3 months, with features of migraine</td></tr><tr><td>Medication-overuse headache</td><td>Present in up to 40% of chronic migraineurs; management is education, explanation and follow-up, with abrupt withdrawal of simple analgesics and triptans but gradual tapering of opioids</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical features</div><table style=\"margin:0\"><tr><th>Feature</th><th>Detail</th></tr><tr><td>Aura</td><td>Reversible visual disturbance (homonymous hemianopia, tunnel vision, scotoma, photopsia) &plusmn; photophobia, phonophobia, paraesthesia, hemiplegia, aphasia, nausea, vomiting, abdominal discomfort, diarrhoea</td></tr><tr><td>Headache</td><td>Unilateral (60%) or bilateral (40%), lasting 4&ndash;72 hours, throbbing/pulsating, moderate&ndash;severe; nausea (90%), vomiting (33%), vertigo, fatigue, confusion, ataxia, drowsiness, photophobia, phonophobia, nasal congestion</td></tr><tr><td>Aggravating factors</td><td>Postural change, activity, raised ICP</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Diagnostic criteria &mdash; migraine without aura</div><table style=\"margin:0\"><tr><th>Component</th><th>Requirement</th></tr><tr><td>Attack frequency</td><td>At least 5 attacks fulfilling all criteria below</td></tr><tr><td>Duration</td><td>4&ndash;72 hours (untreated or unsuccessfully treated)</td></tr><tr><td>Headache features (&ge;2 required)</td><td>Unilateral; pulsating quality; moderate to severe intensity; exacerbated by routine physical activity</td></tr><tr><td>Associated features (&ge;1 required)</td><td>Nausea and/or vomiting; photophobia or phonophobia</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Diagnostic criteria &mdash; migraine with aura</div><table style=\"margin:0\"><tr><th>Component</th><th>Requirement</th></tr><tr><td>Attack frequency</td><td>At least 2 attacks associated with aura symptoms</td></tr><tr><td>Aura symptom type (&ge;1 required)</td><td>Visual; sensory; speech or language; motor; brainstem; retinal</td></tr><tr><td>Aura characteristics (&ge;3 required)</td><td>Gradual spread over &ge;5 min for at least one symptom; stepwise, successive onset of aura symptoms; each symptom resolves within 60 min; at least one unilateral symptom; at least one positive symptom; headache occurs during aura, or within 60 min of aura onset</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Treatment</div><table style=\"margin:0\"><tr><th>Area</th><th>Approach</th></tr><tr><td>Stress</td><td>Lifestyle change, relaxation therapy, coping strategies, biofeedback, hypnotherapy</td></tr><tr><td>Depression / anxiety</td><td>Specific therapy</td></tr><tr><td>Menstrual migraine</td><td>Mefenamic acid, frovatriptan, transdermal oestrogen, COCP, oestrogen/progesterone implants</td></tr><tr><td>Acute &mdash; stepped management</td><td>1. Simple oral analgesic + antiemetic (aspirin/ibuprofen/tolfenamic acid + prochlorperazine/domperidone/metoclopramide)<br>2. Triptan (sumatriptan, zolmitriptan, rizatriptan, naratriptan) + antiemetic, or ergotamine for recurrent relapse<br>3. CGRP receptor antagonists (gepants)<br>Opioids provide only a small additional benefit</td></tr><tr><td>Prophylaxis</td><td>1st line: &beta;-blockers, tricyclic antidepressants, ACE inhibitors / angiotensin receptor blockers<br>2nd line: topiramate, sodium valproate<br>3rd line: CGRP monoclonal antibodies</td></tr><tr><td>Non-drug</td><td>Botulinum toxin injections, greater occipital nerve blocks, non-invasive neuromodulation therapies</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Sodium valproate and topiramate both carry MHRA pregnancy prevention requirements &mdash; avoid in women of childbearing potential unless the conditions of the pregnancy prevention programme are met.</p></div>\n  </div>\n</div></div>","relevantReading":[{"label":"Headache and chronic facial pain","source":"BJA Education","url":"https://www.bjaed.org/article/S1743-1816(17)30474-2/fulltext"},{"label":"Migraine: symptoms, types, pathophysiology and diagnosis","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(25)00072-1/fulltext"},{"label":"Migraine part 2: evidence-based acute and preventive treatment","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(25)00104-0/fulltext"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_migraine_acute_triptan_001', 'SBA', '{"dateAdded":"2026-10-16","rotationIndex":161,"question":"A 30-year-old woman has recurrent unilateral throbbing headaches lasting about a day, with nausea and photophobia but no vomiting. Ibuprofen with metoclopramide taken early in an attack gives inadequate relief. Which is the most appropriate next step for acute treatment?","choices":["Oral sumatriptan","Nasal triptan","Propranolol","Greater occipital nerve block","Erenumab"],"correct":0,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Acute migraine treatment is stepped. A simple oral analgesic (aspirin or ibuprofen) with an antiemetic is tried first; if this fails, a triptan (with an antiemetic) is the next step.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Correct.</strong> Triptans (5-HT1B/1D agonists) are the recommended next step when a simple analgesic plus antiemetic is inadequate.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> A nasal triptan works by the same mechanism, but it is usually reserved for patients who vomit or cannot take tablets; this patient is not vomiting and can use the oral route, so an oral triptan is the first choice.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> Propranolol is a prophylactic agent and does not abort an established attack.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Greater occipital nerve block is a non-drug option used in selected patients, not the next step for an individual acute attack.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Erenumab is a CGRP monoclonal antibody used for prophylaxis, not for acute treatment.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Migraine</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\">\n    <div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Migraine is a primary headache disorder of recurrent attacks of moderate-to-severe, typically unilateral and pulsating headache with autonomic and sensory features (nausea, photophobia, phonophobia), in some patients preceded or accompanied by transient, fully reversible neurological symptoms (aura). It is thought to arise from neuronal hyperexcitability (cortical spreading depression, particularly relevant to aura) and activation of the trigeminovascular system, with release of vasoactive neuropeptides (e.g. CGRP) and central sensitisation.</p></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Epidemiology and types</div><table style=\"margin:0\"><tr><th>Feature</th><th>Detail</th></tr><tr><td>Epidemiology</td><td>Incidence 8.1/1000; male:female ratio ~1:3; onset commonly in the 2nd&ndash;3rd decade; 70% have a positive family history</td></tr><tr><td>Types</td><td>Migraine without aura (70%) and migraine with aura (30%, &ldquo;classic migraine&rdquo;)</td></tr><tr><td>Episodic migraine</td><td>Headache on fewer than 15 days per month</td></tr><tr><td>Chronic migraine</td><td>Headache on &ge;15 days per month for &gt;3 months, with features of migraine</td></tr><tr><td>Medication-overuse headache</td><td>Present in up to 40% of chronic migraineurs; management is education, explanation and follow-up, with abrupt withdrawal of simple analgesics and triptans but gradual tapering of opioids</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical features</div><table style=\"margin:0\"><tr><th>Feature</th><th>Detail</th></tr><tr><td>Aura</td><td>Reversible visual disturbance (homonymous hemianopia, tunnel vision, scotoma, photopsia) &plusmn; photophobia, phonophobia, paraesthesia, hemiplegia, aphasia, nausea, vomiting, abdominal discomfort, diarrhoea</td></tr><tr><td>Headache</td><td>Unilateral (60%) or bilateral (40%), lasting 4&ndash;72 hours, throbbing/pulsating, moderate&ndash;severe; nausea (90%), vomiting (33%), vertigo, fatigue, confusion, ataxia, drowsiness, photophobia, phonophobia, nasal congestion</td></tr><tr><td>Aggravating factors</td><td>Postural change, activity, raised ICP</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Diagnostic criteria &mdash; migraine without aura</div><table style=\"margin:0\"><tr><th>Component</th><th>Requirement</th></tr><tr><td>Attack frequency</td><td>At least 5 attacks fulfilling all criteria below</td></tr><tr><td>Duration</td><td>4&ndash;72 hours (untreated or unsuccessfully treated)</td></tr><tr><td>Headache features (&ge;2 required)</td><td>Unilateral; pulsating quality; moderate to severe intensity; exacerbated by routine physical activity</td></tr><tr><td>Associated features (&ge;1 required)</td><td>Nausea and/or vomiting; photophobia or phonophobia</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Diagnostic criteria &mdash; migraine with aura</div><table style=\"margin:0\"><tr><th>Component</th><th>Requirement</th></tr><tr><td>Attack frequency</td><td>At least 2 attacks associated with aura symptoms</td></tr><tr><td>Aura symptom type (&ge;1 required)</td><td>Visual; sensory; speech or language; motor; brainstem; retinal</td></tr><tr><td>Aura characteristics (&ge;3 required)</td><td>Gradual spread over &ge;5 min for at least one symptom; stepwise, successive onset of aura symptoms; each symptom resolves within 60 min; at least one unilateral symptom; at least one positive symptom; headache occurs during aura, or within 60 min of aura onset</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Treatment</div><table style=\"margin:0\"><tr><th>Area</th><th>Approach</th></tr><tr><td>Stress</td><td>Lifestyle change, relaxation therapy, coping strategies, biofeedback, hypnotherapy</td></tr><tr><td>Depression / anxiety</td><td>Specific therapy</td></tr><tr><td>Menstrual migraine</td><td>Mefenamic acid, frovatriptan, transdermal oestrogen, COCP, oestrogen/progesterone implants</td></tr><tr><td>Acute &mdash; stepped management</td><td>1. Simple oral analgesic + antiemetic (aspirin/ibuprofen/tolfenamic acid + prochlorperazine/domperidone/metoclopramide)<br>2. Triptan (sumatriptan, zolmitriptan, rizatriptan, naratriptan) + antiemetic, or ergotamine for recurrent relapse<br>3. CGRP receptor antagonists (gepants)<br>Opioids provide only a small additional benefit</td></tr><tr><td>Prophylaxis</td><td>1st line: &beta;-blockers, tricyclic antidepressants, ACE inhibitors / angiotensin receptor blockers<br>2nd line: topiramate, sodium valproate<br>3rd line: CGRP monoclonal antibodies</td></tr><tr><td>Non-drug</td><td>Botulinum toxin injections, greater occipital nerve blocks, non-invasive neuromodulation therapies</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Sodium valproate and topiramate both carry MHRA pregnancy prevention requirements &mdash; avoid in women of childbearing potential unless the conditions of the pregnancy prevention programme are met.</p></div>\n  </div>\n</div></div>","relevantReading":[{"label":"Headache and chronic facial pain","source":"BJA Education","url":"https://www.bjaed.org/article/S1743-1816(17)30474-2/fulltext"},{"label":"Migraine: symptoms, types, pathophysiology and diagnosis","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(25)00072-1/fulltext"},{"label":"Migraine part 2: evidence-based acute and preventive treatment","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(25)00104-0/fulltext"}]}'::jsonb, 'published')
