insert into questions (id, type, data, status) values ('q_mtf_migraine_features_001', 'MTF', '{"dateAdded":"2026-10-16","rotationIndex":162,"stem":"Regarding migraine:","choices":["Migraine without aura is more common than migraine with aura","It is about three times more common in women than in men","Vomiting occurs in most patients during an attack","Headache is bilateral in the majority of patients","A positive family history is present in around 70% of patients"],"correct":[true,true,false,false,true],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Migraine is a common primary headache disorder with a strong familial component and a female predominance.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. TRUE</strong> &mdash; About 70% of patients have migraine without aura and about 30% have migraine with aura.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. TRUE</strong> &mdash; The male-to-female ratio is approximately 1:3, with onset commonly in the second to third decade.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. FALSE</strong> &mdash; Nausea is very common (around 90%), but vomiting occurs in only about a third of patients.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. FALSE</strong> &mdash; Headache is unilateral in about 60% and bilateral in about 40%.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. TRUE</strong> &mdash; Around 70% of patients have a positive family history.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Migraine</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\">\n    <div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Migraine is a primary headache disorder of recurrent attacks of moderate-to-severe, typically unilateral and pulsating headache with autonomic and sensory features (nausea, photophobia, phonophobia), in some patients preceded or accompanied by transient, fully reversible neurological symptoms (aura). It is thought to arise from neuronal hyperexcitability (cortical spreading depression, particularly relevant to aura) and activation of the trigeminovascular system, with release of vasoactive neuropeptides (e.g. CGRP) and central sensitisation.</p></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Epidemiology and types</div><table style=\"margin:0\"><tr><th>Feature</th><th>Detail</th></tr><tr><td>Epidemiology</td><td>Incidence 8.1/1000; male:female ratio ~1:3; onset commonly in the 2nd&ndash;3rd decade; 70% have a positive family history</td></tr><tr><td>Types</td><td>Migraine without aura (70%) and migraine with aura (30%, &ldquo;classic migraine&rdquo;)</td></tr><tr><td>Episodic migraine</td><td>Headache on fewer than 15 days per month</td></tr><tr><td>Chronic migraine</td><td>Headache on &ge;15 days per month for &gt;3 months, with features of migraine</td></tr><tr><td>Medication-overuse headache</td><td>Present in up to 40% of chronic migraineurs; management is education, explanation and follow-up, with abrupt withdrawal of simple analgesics and triptans but gradual tapering of opioids</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical features</div><table style=\"margin:0\"><tr><th>Feature</th><th>Detail</th></tr><tr><td>Aura</td><td>Reversible visual disturbance (homonymous hemianopia, tunnel vision, scotoma, photopsia) &plusmn; photophobia, phonophobia, paraesthesia, hemiplegia, aphasia, nausea, vomiting, abdominal discomfort, diarrhoea</td></tr><tr><td>Headache</td><td>Unilateral (60%) or bilateral (40%), lasting 4&ndash;72 hours, throbbing/pulsating, moderate&ndash;severe; nausea (90%), vomiting (33%), vertigo, fatigue, confusion, ataxia, drowsiness, photophobia, phonophobia, nasal congestion</td></tr><tr><td>Aggravating factors</td><td>Postural change, activity, raised ICP</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Diagnostic criteria &mdash; migraine without aura</div><table style=\"margin:0\"><tr><th>Component</th><th>Requirement</th></tr><tr><td>Attack frequency</td><td>At least 5 attacks fulfilling all criteria below</td></tr><tr><td>Duration</td><td>4&ndash;72 hours (untreated or unsuccessfully treated)</td></tr><tr><td>Headache features (&ge;2 required)</td><td>Unilateral; pulsating quality; moderate to severe intensity; exacerbated by routine physical activity</td></tr><tr><td>Associated features (&ge;1 required)</td><td>Nausea and/or vomiting; photophobia or phonophobia</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Diagnostic criteria &mdash; migraine with aura</div><table style=\"margin:0\"><tr><th>Component</th><th>Requirement</th></tr><tr><td>Attack frequency</td><td>At least 2 attacks associated with aura symptoms</td></tr><tr><td>Aura symptom type (&ge;1 required)</td><td>Visual; sensory; speech or language; motor; brainstem; retinal</td></tr><tr><td>Aura characteristics (&ge;3 required)</td><td>Gradual spread over &ge;5 min for at least one symptom; stepwise, successive onset of aura symptoms; each symptom resolves within 60 min; at least one unilateral symptom; at least one positive symptom; headache occurs during aura, or within 60 min of aura onset</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Treatment</div><table style=\"margin:0\"><tr><th>Area</th><th>Approach</th></tr><tr><td>Stress</td><td>Lifestyle change, relaxation therapy, coping strategies, biofeedback, hypnotherapy</td></tr><tr><td>Depression / anxiety</td><td>Specific therapy</td></tr><tr><td>Menstrual migraine</td><td>Mefenamic acid, frovatriptan, transdermal oestrogen, COCP, oestrogen/progesterone implants</td></tr><tr><td>Acute &mdash; stepped management</td><td>1. Simple oral analgesic + antiemetic (aspirin/ibuprofen/tolfenamic acid + prochlorperazine/domperidone/metoclopramide)<br>2. Triptan (sumatriptan, zolmitriptan, rizatriptan, naratriptan) + antiemetic, or ergotamine for recurrent relapse<br>3. CGRP receptor antagonists (gepants)<br>Opioids provide only a small additional benefit</td></tr><tr><td>Prophylaxis</td><td>1st line: &beta;-blockers, tricyclic antidepressants, ACE inhibitors / angiotensin receptor blockers<br>2nd line: topiramate, sodium valproate<br>3rd line: CGRP monoclonal antibodies</td></tr><tr><td>Non-drug</td><td>Botulinum toxin injections, greater occipital nerve blocks, non-invasive neuromodulation therapies</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Sodium valproate and topiramate both carry MHRA pregnancy prevention requirements &mdash; avoid in women of childbearing potential unless the conditions of the pregnancy prevention programme are met.</p></div>\n  </div>\n</div></div>","relevantReading":[{"label":"Headache and chronic facial pain","source":"BJA Education","url":"https://www.bjaed.org/article/S1743-1816(17)30474-2/fulltext"},{"label":"Migraine: symptoms, types, pathophysiology and diagnosis","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(25)00072-1/fulltext"},{"label":"Migraine part 2: evidence-based acute and preventive treatment","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(25)00104-0/fulltext"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_motivational_interviewing_spirit_001', 'MTF', '{"dateAdded":"2026-10-16","rotationIndex":163,"stem":"The spirit of motivational interviewing includes:","choices":["Partnership","Persuasion","Evocation","Confrontation","Acceptance"],"correct":[true,false,true,false,true],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The spirit of motivational interviewing (Miller and Rollnick, 2013) comprises four elements: partnership, acceptance, compassion and evocation. Persuasion and confrontation run against it.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. TRUE</strong> &mdash; Partnership means working collaboratively with the patient, who is the expert on their own life.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. FALSE</strong> &mdash; Persuasion supplies the clinician&rsquo;s argument for change, whereas motivational interviewing draws out the patient&rsquo;s own reasons.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. TRUE</strong> &mdash; Evocation means eliciting the patient&rsquo;s own motivations and reasons for change.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. FALSE</strong> &mdash; Confrontation tends to provoke resistance and sustain talk; the approach is collaborative.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. TRUE</strong> &mdash; Acceptance includes respect for autonomy, accurate empathy and affirmation of the patient&rsquo;s strengths.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Motivational Interviewing</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Definition</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">A <strong>collaborative, patient-centred communication style</strong> for strengthening a person&rsquo;s own motivation and commitment to change, by <strong>exploring and resolving ambivalence</strong>, rather than imposing change through direct persuasion, confrontation or authority.</p><div style=\"text-align:center;margin-top:12px\"><img src=\"images/motivational-interviewing-oars.svg\" alt=\"Motivational interviewing at a glance: the spirit (partnership, acceptance, compassion, evocation), the OARS core skills and the four processes (engaging, focusing, evoking, planning)\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Spirit of Motivational Interviewing (Underlying Philosophy)</div><table style=\"margin:0\"><tr><th>Element</th><th>Meaning</th></tr><tr><td><strong>Partnership</strong></td><td>Working collaboratively <strong>with</strong> the patient, who is the expert on their own life &mdash; collaboration rather than confrontation, not imposing the clinician&rsquo;s expertise</td></tr><tr><td><strong>Acceptance</strong></td><td>Respecting the patient&rsquo;s worth and <strong>autonomy</strong> (their right to make their own choices), with accurate empathy and affirmation of their strengths</td></tr><tr><td><strong>Compassion</strong></td><td>Actively prioritising the patient&rsquo;s welfare and best interests</td></tr><tr><td><strong>Evocation</strong></td><td>Drawing out the patient&rsquo;s <strong>own</strong> motivations and reasons for change, rather than installing motivation from outside</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Miller and Rollnick (3rd edition, 2013).</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Core Techniques &mdash; OARS</div><table style=\"margin:0\"><tr><th>Skill</th><th>What it involves</th></tr><tr><td><strong>O</strong>pen-ended questions</td><td>Encouraging elaboration rather than yes/no answers</td></tr><tr><td><strong>A</strong>ffirmations</td><td>Recognising patient strengths and efforts</td></tr><tr><td><strong>R</strong>eflective listening</td><td>Reflecting back what the patient has said, including their ambivalence, to deepen exploration</td></tr><tr><td><strong>S</strong>ummarising</td><td>Periodically pulling together what has been discussed</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">The Four Processes</div><table style=\"margin:0\"><tr><th>Process</th><th>Purpose</th></tr><tr><td><strong>Engaging</strong></td><td>Building a trusting, collaborative relationship</td></tr><tr><td><strong>Focusing</strong></td><td>Agreeing a direction or target for change</td></tr><tr><td><strong>Evoking</strong></td><td>Drawing out the patient&rsquo;s own reasons for change</td></tr><tr><td><strong>Planning</strong></td><td>Developing commitment and a concrete plan</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical Relevance in Pain Medicine</div><table style=\"margin:0\"><tr><th>Particularly useful for</th></tr><tr><td>Opioid tapering / dose-reduction discussions</td></tr><tr><td>Engagement with exercise and physiotherapy programmes</td></tr><tr><td>Smoking cessation and weight management</td></tr><tr><td>Engagement with multidisciplinary pain management programmes</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_motivational_interviewing_planning_001', 'SBA', '{"dateAdded":"2026-10-16","rotationIndex":164,"question":"A patient with chronic pain has said they want to reduce their opioid dose. The clinician now asks what first step they would feel able to take and agrees a start date and review. Which process of motivational interviewing is being used?","choices":["Engaging","Focusing","Evoking","Planning","Summarising"],"correct":3,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Motivational interviewing has four processes: engaging, focusing, evoking and planning. Once the patient is motivated, the clinician helps develop commitment and a concrete plan.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> Engaging is about building a trusting, collaborative relationship, which comes first.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> Focusing is agreeing a direction or target for change; here the target (reducing the opioid dose) has already been set.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> Evoking is drawing out the patient&rsquo;s own reasons for change; here the patient has already expressed the wish to change.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Correct.</strong> Planning is developing commitment and a concrete plan, such as agreeing a first step, a start date and a review.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Summarising is one of the core skills (OARS) used within the processes, not one of the four processes.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Motivational Interviewing</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Definition</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">A <strong>collaborative, patient-centred communication style</strong> for strengthening a person&rsquo;s own motivation and commitment to change, by <strong>exploring and resolving ambivalence</strong>, rather than imposing change through direct persuasion, confrontation or authority.</p><div style=\"text-align:center;margin-top:12px\"><img src=\"images/motivational-interviewing-oars.svg\" alt=\"Motivational interviewing at a glance: the spirit (partnership, acceptance, compassion, evocation), the OARS core skills and the four processes (engaging, focusing, evoking, planning)\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Spirit of Motivational Interviewing (Underlying Philosophy)</div><table style=\"margin:0\"><tr><th>Element</th><th>Meaning</th></tr><tr><td><strong>Partnership</strong></td><td>Working collaboratively <strong>with</strong> the patient, who is the expert on their own life &mdash; collaboration rather than confrontation, not imposing the clinician&rsquo;s expertise</td></tr><tr><td><strong>Acceptance</strong></td><td>Respecting the patient&rsquo;s worth and <strong>autonomy</strong> (their right to make their own choices), with accurate empathy and affirmation of their strengths</td></tr><tr><td><strong>Compassion</strong></td><td>Actively prioritising the patient&rsquo;s welfare and best interests</td></tr><tr><td><strong>Evocation</strong></td><td>Drawing out the patient&rsquo;s <strong>own</strong> motivations and reasons for change, rather than installing motivation from outside</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Miller and Rollnick (3rd edition, 2013).</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Core Techniques &mdash; OARS</div><table style=\"margin:0\"><tr><th>Skill</th><th>What it involves</th></tr><tr><td><strong>O</strong>pen-ended questions</td><td>Encouraging elaboration rather than yes/no answers</td></tr><tr><td><strong>A</strong>ffirmations</td><td>Recognising patient strengths and efforts</td></tr><tr><td><strong>R</strong>eflective listening</td><td>Reflecting back what the patient has said, including their ambivalence, to deepen exploration</td></tr><tr><td><strong>S</strong>ummarising</td><td>Periodically pulling together what has been discussed</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">The Four Processes</div><table style=\"margin:0\"><tr><th>Process</th><th>Purpose</th></tr><tr><td><strong>Engaging</strong></td><td>Building a trusting, collaborative relationship</td></tr><tr><td><strong>Focusing</strong></td><td>Agreeing a direction or target for change</td></tr><tr><td><strong>Evoking</strong></td><td>Drawing out the patient&rsquo;s own reasons for change</td></tr><tr><td><strong>Planning</strong></td><td>Developing commitment and a concrete plan</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical Relevance in Pain Medicine</div><table style=\"margin:0\"><tr><th>Particularly useful for</th></tr><tr><td>Opioid tapering / dose-reduction discussions</td></tr><tr><td>Engagement with exercise and physiotherapy programmes</td></tr><tr><td>Smoking cessation and weight management</td></tr><tr><td>Engagement with multidisciplinary pain management programmes</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_motivational_interviewing_affirmation_001', 'SBA', '{"dateAdded":"2026-10-16","rotationIndex":165,"question":"During a consultation about activity, a clinician says to a patient with chronic pain, \"You have kept up your daily walks even on the bad days, which shows real commitment.\" Which core communication skill is this?","choices":["Open-ended question","Affirmation","Reflective listening","Summarising","Giving advice"],"correct":1,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The core skills of motivational interviewing are remembered as OARS: open-ended questions, affirmations, reflective listening and summarising. This statement recognises the patient&rsquo;s strengths and efforts.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> An open-ended question invites elaboration; the statement contains no question.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Correct.</strong> Affirmations recognise the patient&rsquo;s strengths and efforts and support their confidence to change.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> Reflective listening mirrors back what the patient has said, including ambivalence; the clinician here is commenting on effort, not reflecting meaning.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Summarising pulls together what has been discussed; no summary is given here.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Giving advice would tell the patient what to do; the clinician is not directing a course of action.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Motivational Interviewing</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Definition</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">A <strong>collaborative, patient-centred communication style</strong> for strengthening a person&rsquo;s own motivation and commitment to change, by <strong>exploring and resolving ambivalence</strong>, rather than imposing change through direct persuasion, confrontation or authority.</p><div style=\"text-align:center;margin-top:12px\"><img src=\"images/motivational-interviewing-oars.svg\" alt=\"Motivational interviewing at a glance: the spirit (partnership, acceptance, compassion, evocation), the OARS core skills and the four processes (engaging, focusing, evoking, planning)\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Spirit of Motivational Interviewing (Underlying Philosophy)</div><table style=\"margin:0\"><tr><th>Element</th><th>Meaning</th></tr><tr><td><strong>Partnership</strong></td><td>Working collaboratively <strong>with</strong> the patient, who is the expert on their own life &mdash; collaboration rather than confrontation, not imposing the clinician&rsquo;s expertise</td></tr><tr><td><strong>Acceptance</strong></td><td>Respecting the patient&rsquo;s worth and <strong>autonomy</strong> (their right to make their own choices), with accurate empathy and affirmation of their strengths</td></tr><tr><td><strong>Compassion</strong></td><td>Actively prioritising the patient&rsquo;s welfare and best interests</td></tr><tr><td><strong>Evocation</strong></td><td>Drawing out the patient&rsquo;s <strong>own</strong> motivations and reasons for change, rather than installing motivation from outside</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Miller and Rollnick (3rd edition, 2013).</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Core Techniques &mdash; OARS</div><table style=\"margin:0\"><tr><th>Skill</th><th>What it involves</th></tr><tr><td><strong>O</strong>pen-ended questions</td><td>Encouraging elaboration rather than yes/no answers</td></tr><tr><td><strong>A</strong>ffirmations</td><td>Recognising patient strengths and efforts</td></tr><tr><td><strong>R</strong>eflective listening</td><td>Reflecting back what the patient has said, including their ambivalence, to deepen exploration</td></tr><tr><td><strong>S</strong>ummarising</td><td>Periodically pulling together what has been discussed</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">The Four Processes</div><table style=\"margin:0\"><tr><th>Process</th><th>Purpose</th></tr><tr><td><strong>Engaging</strong></td><td>Building a trusting, collaborative relationship</td></tr><tr><td><strong>Focusing</strong></td><td>Agreeing a direction or target for change</td></tr><tr><td><strong>Evoking</strong></td><td>Drawing out the patient&rsquo;s own reasons for change</td></tr><tr><td><strong>Planning</strong></td><td>Developing commitment and a concrete plan</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical Relevance in Pain Medicine</div><table style=\"margin:0\"><tr><th>Particularly useful for</th></tr><tr><td>Opioid tapering / dose-reduction discussions</td></tr><tr><td>Engagement with exercise and physiotherapy programmes</td></tr><tr><td>Smoking cessation and weight management</td></tr><tr><td>Engagement with multidisciplinary pain management programmes</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_pudendal_nerve_anatomy_001', 'MTF', '{"dateAdded":"2026-10-16","rotationIndex":166,"stem":"Regarding the pudendal nerve:","choices":["It arises from the ventral rami of S2 to S4","It leaves the pelvis through the greater sciatic foramen","It leaves the pelvis through the obturator canal","It runs in a canal formed by the fascia of obturator internus","It provides sensation to the skin of the medial thigh"],"correct":[true,true,false,true,false],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The pudendal nerve is a branch of the sacral plexus supplying the perineum and external genitalia.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. TRUE</strong> &mdash; It arises from the ventral rami of S2, S3 and S4.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. TRUE</strong> &mdash; It exits the pelvis below piriformis through the greater sciatic foramen, passes behind the ischial spine and re-enters through the lesser sciatic foramen.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. FALSE</strong> &mdash; The obturator canal transmits the obturator nerve and vessels, not the pudendal nerve.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. TRUE</strong> &mdash; The pudendal (Alcock&rsquo;s) canal is a fascial tunnel in the obturator internus fascia.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. FALSE</strong> &mdash; Its sensory territory is the perineum, anal canal skin and external genitalia; the medial thigh is supplied by the obturator and other nerves.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Pudendal Neuralgia</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\">\n    <div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Pudendal neuralgia is neuropathic pain in the territory of the pudendal nerve, most often due to entrapment or compression of the nerve along its course through the pelvis and perineum. The diagnosis is clinical, based on the Nantes criteria, and confirmed by a positive response to a pudendal nerve block.</p></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Anatomy of the pudendal nerve</div><table style=\"margin:0\"><tr><th>Feature</th><th>Detail</th></tr><tr><td>Origin</td><td>Ventral rami of S2&ndash;S4 (sacral plexus)</td></tr><tr><td>Course</td><td>Leaves the pelvis through the greater sciatic foramen below piriformis, passes behind the ischial spine and sacrospinous ligament (between the sacrospinous and sacrotuberous ligaments), then re-enters the perineum through the lesser sciatic foramen</td></tr><tr><td>Pudendal (Alcock&rsquo;s) canal</td><td>A fascial tunnel in the obturator internus fascia on the lateral wall of the ischioanal fossa, carrying the nerve with the internal pudendal vessels</td></tr><tr><td>Terminal branches</td><td>Inferior rectal nerve, perineal nerve and dorsal nerve of the penis/clitoris</td></tr><tr><td>Sensory supply</td><td>Perineum, anal canal skin and external genitalia</td></tr><tr><td>Motor supply</td><td>External anal and external urethral sphincters and the perineal muscles</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Sites of entrapment and risk factors</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Commonest site: between the sacrospinous and sacrotuberous ligaments, near the ischial spine</td></tr><tr><td>Other sites: pudendal (Alcock&rsquo;s) canal and the falciform process of the sacrotuberous ligament</td></tr><tr><td>Risk factors: prolonged sitting and cycling, childbirth, pelvic surgery or trauma, chronic straining or constipation</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Nantes criteria (essential diagnostic criteria)</div><table style=\"margin:0\"><tr><th>Criterion</th></tr><tr><td>Pain in the anatomical territory of the pudendal nerve (anus to clitoris/penis)</td></tr><tr><td>Pain predominantly experienced while sitting</td></tr><tr><td>The patient is not woken at night by the pain</td></tr><tr><td>No objective sensory impairment on clinical examination</td></tr><tr><td>Pain relieved by a diagnostic pudendal nerve block</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">All five are required. Supportive features include burning, shooting or stabbing pain, allodynia or hyperpathia, a foreign-body sensation in the rectum or vagina, pain worsening through the day, and tenderness on palpation of the ischial spine. Exclusion criteria include pain confined to the coccygeal, gluteal, pubic or hypogastric areas, purely paroxysmal pain, pruritus as the only symptom, and imaging abnormalities that explain the pain.</p></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Management</div><table style=\"margin:0\"><tr><th>Step</th><th>Approach</th></tr><tr><td>Conservative</td><td>Education, avoiding aggravating postures (sitting-aid cushions, avoiding cycling), pelvic floor physiotherapy, treating constipation</td></tr><tr><td>Pharmacological</td><td>Neuropathic agents such as amitriptyline or gabapentinoids; opioids are not recommended as first line</td></tr><tr><td>Interventional</td><td>Pudendal nerve block with local anaesthetic &plusmn; corticosteroid (image-guided, at the ischial spine) is both diagnostic and therapeutic; pulsed radiofrequency and neuromodulation in refractory cases</td></tr><tr><td>Surgical</td><td>Pudendal nerve decompression for selected patients refractory to conservative and interventional treatment</td></tr></table></div>\n  </div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_pudendal_neuralgia_diagnostic_feature_001', 'SBA', '{"dateAdded":"2026-10-16","rotationIndex":167,"question":"A 45-year-old man who cycles regularly has burning perineal pain extending from the anus to the penis, with an anaesthetic nerve block giving relief. Which feature is required to support a diagnosis of pudendal neuralgia?","choices":["Pain predominantly on sitting","Pain that wakes him at night","Objective sensory loss in the perineum","Pain confined to the coccyx","Prolonged pudendal nerve terminal motor latency"],"correct":0,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The Nantes criteria require pain in the pudendal territory, predominantly on sitting, not waking the patient at night, with no objective sensory impairment, and relief with a pudendal nerve block.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Correct.</strong> Pain that is predominantly experienced while sitting is one of the essential criteria.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> Pain waking the patient at night argues against pudendal neuralgia; the pain is not expected to disturb sleep.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> Objective sensory impairment on examination is absent in pudendal neuralgia, and its presence suggests another cause.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Pain confined to the coccygeal, gluteal, pubic or hypogastric area is an exclusion criterion.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Neurophysiology is not part of the essential criteria; it may help exclude other neuropathies but a prolonged latency is neither required nor diagnostic.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Pudendal Neuralgia</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\">\n    <div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Pudendal neuralgia is neuropathic pain in the territory of the pudendal nerve, most often due to entrapment or compression of the nerve along its course through the pelvis and perineum. The diagnosis is clinical, based on the Nantes criteria, and confirmed by a positive response to a pudendal nerve block.</p></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Anatomy of the pudendal nerve</div><table style=\"margin:0\"><tr><th>Feature</th><th>Detail</th></tr><tr><td>Origin</td><td>Ventral rami of S2&ndash;S4 (sacral plexus)</td></tr><tr><td>Course</td><td>Leaves the pelvis through the greater sciatic foramen below piriformis, passes behind the ischial spine and sacrospinous ligament (between the sacrospinous and sacrotuberous ligaments), then re-enters the perineum through the lesser sciatic foramen</td></tr><tr><td>Pudendal (Alcock&rsquo;s) canal</td><td>A fascial tunnel in the obturator internus fascia on the lateral wall of the ischioanal fossa, carrying the nerve with the internal pudendal vessels</td></tr><tr><td>Terminal branches</td><td>Inferior rectal nerve, perineal nerve and dorsal nerve of the penis/clitoris</td></tr><tr><td>Sensory supply</td><td>Perineum, anal canal skin and external genitalia</td></tr><tr><td>Motor supply</td><td>External anal and external urethral sphincters and the perineal muscles</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Sites of entrapment and risk factors</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Commonest site: between the sacrospinous and sacrotuberous ligaments, near the ischial spine</td></tr><tr><td>Other sites: pudendal (Alcock&rsquo;s) canal and the falciform process of the sacrotuberous ligament</td></tr><tr><td>Risk factors: prolonged sitting and cycling, childbirth, pelvic surgery or trauma, chronic straining or constipation</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Nantes criteria (essential diagnostic criteria)</div><table style=\"margin:0\"><tr><th>Criterion</th></tr><tr><td>Pain in the anatomical territory of the pudendal nerve (anus to clitoris/penis)</td></tr><tr><td>Pain predominantly experienced while sitting</td></tr><tr><td>The patient is not woken at night by the pain</td></tr><tr><td>No objective sensory impairment on clinical examination</td></tr><tr><td>Pain relieved by a diagnostic pudendal nerve block</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">All five are required. Supportive features include burning, shooting or stabbing pain, allodynia or hyperpathia, a foreign-body sensation in the rectum or vagina, pain worsening through the day, and tenderness on palpation of the ischial spine. Exclusion criteria include pain confined to the coccygeal, gluteal, pubic or hypogastric areas, purely paroxysmal pain, pruritus as the only symptom, and imaging abnormalities that explain the pain.</p></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Management</div><table style=\"margin:0\"><tr><th>Step</th><th>Approach</th></tr><tr><td>Conservative</td><td>Education, avoiding aggravating postures (sitting-aid cushions, avoiding cycling), pelvic floor physiotherapy, treating constipation</td></tr><tr><td>Pharmacological</td><td>Neuropathic agents such as amitriptyline or gabapentinoids; opioids are not recommended as first line</td></tr><tr><td>Interventional</td><td>Pudendal nerve block with local anaesthetic &plusmn; corticosteroid (image-guided, at the ischial spine) is both diagnostic and therapeutic; pulsed radiofrequency and neuromodulation in refractory cases</td></tr><tr><td>Surgical</td><td>Pudendal nerve decompression for selected patients refractory to conservative and interventional treatment</td></tr></table></div>\n  </div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_pudendal_neuralgia_management_001', 'MTF', '{"dateAdded":"2026-10-16","rotationIndex":168,"stem":"Regarding the management of pudendal neuralgia:","choices":["Pudendal nerve block can be both diagnostic and therapeutic","Amitriptyline can be used","Avoiding prolonged sitting and cycling is advised","Opioids are recommended first line","Surgical decompression is the first step"],"correct":[true,true,true,false,false],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Management is stepwise: conservative measures and neuropathic agents first, then image-guided pudendal nerve blocks, with neuromodulation or surgery reserved for refractory cases.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. TRUE</strong> &mdash; A pudendal block with local anaesthetic (&plusmn; steroid) confirms the diagnosis if it relieves pain and can give therapeutic benefit.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. TRUE</strong> &mdash; Neuropathic agents such as amitriptyline or gabapentinoids are used.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. TRUE</strong> &mdash; Avoiding aggravating factors, with sitting aids and pelvic floor physiotherapy, forms part of conservative management.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. FALSE</strong> &mdash; Opioids are not recommended as first-line treatment for neuropathic pain of this kind.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. FALSE</strong> &mdash; Decompression is reserved for selected patients who fail conservative and interventional treatment.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Pudendal Neuralgia</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\">\n    <div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Pudendal neuralgia is neuropathic pain in the territory of the pudendal nerve, most often due to entrapment or compression of the nerve along its course through the pelvis and perineum. The diagnosis is clinical, based on the Nantes criteria, and confirmed by a positive response to a pudendal nerve block.</p></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Anatomy of the pudendal nerve</div><table style=\"margin:0\"><tr><th>Feature</th><th>Detail</th></tr><tr><td>Origin</td><td>Ventral rami of S2&ndash;S4 (sacral plexus)</td></tr><tr><td>Course</td><td>Leaves the pelvis through the greater sciatic foramen below piriformis, passes behind the ischial spine and sacrospinous ligament (between the sacrospinous and sacrotuberous ligaments), then re-enters the perineum through the lesser sciatic foramen</td></tr><tr><td>Pudendal (Alcock&rsquo;s) canal</td><td>A fascial tunnel in the obturator internus fascia on the lateral wall of the ischioanal fossa, carrying the nerve with the internal pudendal vessels</td></tr><tr><td>Terminal branches</td><td>Inferior rectal nerve, perineal nerve and dorsal nerve of the penis/clitoris</td></tr><tr><td>Sensory supply</td><td>Perineum, anal canal skin and external genitalia</td></tr><tr><td>Motor supply</td><td>External anal and external urethral sphincters and the perineal muscles</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Sites of entrapment and risk factors</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Commonest site: between the sacrospinous and sacrotuberous ligaments, near the ischial spine</td></tr><tr><td>Other sites: pudendal (Alcock&rsquo;s) canal and the falciform process of the sacrotuberous ligament</td></tr><tr><td>Risk factors: prolonged sitting and cycling, childbirth, pelvic surgery or trauma, chronic straining or constipation</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Nantes criteria (essential diagnostic criteria)</div><table style=\"margin:0\"><tr><th>Criterion</th></tr><tr><td>Pain in the anatomical territory of the pudendal nerve (anus to clitoris/penis)</td></tr><tr><td>Pain predominantly experienced while sitting</td></tr><tr><td>The patient is not woken at night by the pain</td></tr><tr><td>No objective sensory impairment on clinical examination</td></tr><tr><td>Pain relieved by a diagnostic pudendal nerve block</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">All five are required. Supportive features include burning, shooting or stabbing pain, allodynia or hyperpathia, a foreign-body sensation in the rectum or vagina, pain worsening through the day, and tenderness on palpation of the ischial spine. Exclusion criteria include pain confined to the coccygeal, gluteal, pubic or hypogastric areas, purely paroxysmal pain, pruritus as the only symptom, and imaging abnormalities that explain the pain.</p></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Management</div><table style=\"margin:0\"><tr><th>Step</th><th>Approach</th></tr><tr><td>Conservative</td><td>Education, avoiding aggravating postures (sitting-aid cushions, avoiding cycling), pelvic floor physiotherapy, treating constipation</td></tr><tr><td>Pharmacological</td><td>Neuropathic agents such as amitriptyline or gabapentinoids; opioids are not recommended as first line</td></tr><tr><td>Interventional</td><td>Pudendal nerve block with local anaesthetic &plusmn; corticosteroid (image-guided, at the ischial spine) is both diagnostic and therapeutic; pulsed radiofrequency and neuromodulation in refractory cases</td></tr><tr><td>Surgical</td><td>Pudendal nerve decompression for selected patients refractory to conservative and interventional treatment</td></tr></table></div>\n  </div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_narcotic_bowel_syndrome_diagnosis_001', 'SBA', '{"dateAdded":"2026-10-16","rotationIndex":169,"question":"A 48-year-old woman has had chronic abdominal pain for 3 years, treated with escalating doses of oral morphine. The pain is now worse and diffuse, with bloating and nausea. It intensifies as each dose wears off and eases after the next dose. CT and colonoscopy are normal. What is the most likely diagnosis?","choices":["Narcotic bowel syndrome","Opioid-induced constipation","Irritable bowel syndrome","Chronic mesenteric ischaemia","Opioid toxicity"],"correct":0,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Chronic abdominal pain that worsens with escalating opioid dosing, is not explained by gastrointestinal pathology, and worsens as the dose wanes before improving with the next dose fits narcotic bowel syndrome.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Correct.</strong> The pain is not explained by gastrointestinal disease, worsens with escalating opioid and flares as each dose wears off, meeting the Rome IV criteria.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> Opioid-induced constipation presents with infrequent stools and straining rather than escalating diffuse abdominal pain linked to opioid dosing.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> Irritable bowel syndrome would not explain the relationship of pain to opioid dosing and escalation.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Chronic mesenteric ischaemia causes postprandial pain with weight loss and would be expected to show vascular changes on imaging.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Opioid toxicity causes sedation, respiratory depression and pinpoint pupils rather than worsening abdominal pain.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Narcotic Bowel Syndrome</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\">\n    <div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Narcotic bowel syndrome (opioid-induced gastrointestinal hyperalgesia) is a paradoxical condition in which chronic or recurrent abdominal pain persists or worsens despite continued or escalating opioid doses. It is distinct from opioid-induced constipation, and treating it with more opioid makes it worse.</p></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Rome IV diagnostic criteria</div><table style=\"margin:0\"><tr><th>Criterion</th></tr><tr><td>Chronic or frequently recurring abdominal pain treated with acute high-dose or chronic opioids</td></tr><tr><td>The nature and intensity of the pain is not explained by a current or previous gastrointestinal diagnosis</td></tr><tr><td>Two or more of the following:<br>&bull; Pain worsens or incompletely resolves with continued or escalating opioid doses<br>&bull; Marked worsening of pain as the opioid dose wanes, with improvement when opioids are reinstituted<br>&bull; Progression of the frequency, duration and intensity of pain episodes</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">All criteria must be met. The pattern of pain worsening as each dose wears off and easing after the next dose is often described as &ldquo;soar and crash&rdquo;.</p></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical features and mechanisms</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Often diffuse, poorly localised abdominal pain with nausea, vomiting, bloating and constipation; investigations (imaging, endoscopy) are unrevealing</td></tr><tr><td>Thought to reflect opioid-induced hyperalgesia (central sensitisation, including NMDA receptor activation and spinal dynorphin upregulation) together with opioid effects on the enteric nervous system</td></tr><tr><td>Develops on prolonged or high-dose use, most often with opioids prescribed for chronic non-cancer abdominal pain or after abdominal surgery</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Narcotic bowel syndrome versus opioid-induced constipation</div><table style=\"margin:0\"><tr><th>Feature</th><th>Narcotic bowel syndrome</th><th>Opioid-induced constipation</th></tr><tr><td>Main problem</td><td>Abdominal pain that worsens with opioid</td><td>Reduced bowel frequency, straining, incomplete evacuation</td></tr><tr><td>Effect of more opioid</td><td>Pain worsens</td><td>Constipation worsens</td></tr><tr><td>Effect of reducing opioid</td><td>Pain improves once withdrawal settles</td><td>Bowel function improves</td></tr><tr><td>Treatment</td><td>Opioid withdrawal</td><td>Laxatives; peripheral opioid antagonists (e.g. naloxegol, methylnaltrexone)</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Management</div><table style=\"margin:0\"><tr><th>Step</th><th>Approach</th></tr><tr><td>Recognise and explain</td><td>Explain that the opioid is contributing to the pain; agree a plan and avoid further dose escalation</td></tr><tr><td>Withdraw the opioid</td><td>Structured, supervised opioid reduction or withdrawal (specialist or inpatient support for high doses); pain often worsens transiently before improving</td></tr><tr><td>Support during withdrawal</td><td>Adjuncts such as clonidine for autonomic withdrawal symptoms, and neuropathic or visceral pain agents (e.g. tricyclic antidepressants, gabapentinoids)</td></tr><tr><td>Bowel and psychosocial care</td><td>Laxatives for constipation; psychological support, including cognitive behavioural approaches</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Evidence is largely from case series and expert consensus rather than trials.</p></div>\n  </div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_narcotic_bowel_syndrome_features_001', 'MTF', '{"dateAdded":"2026-10-16","rotationIndex":170,"stem":"Regarding narcotic bowel syndrome:","choices":["Pain worsens with continued or escalating opioid doses","The pain is explained by a structural gastrointestinal lesion","Opioid-induced hyperalgesia is thought to contribute","Increasing the opioid dose usually resolves the pain","Pain worsens as the opioid dose wanes"],"correct":[true,false,true,false,true],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Narcotic bowel syndrome is defined by Rome IV as abdominal pain treated with opioids that is not explained by gastrointestinal disease and that behaves paradoxically in relation to opioid dosing.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. TRUE</strong> &mdash; Pain that worsens or incompletely resolves with continued or escalating opioid doses is one of the diagnostic features.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. FALSE</strong> &mdash; By definition the pain is not explained by a current or previous gastrointestinal diagnosis.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. TRUE</strong> &mdash; Opioid-induced hyperalgesia (central sensitisation with NMDA activation and spinal dynorphin upregulation) is thought to contribute, along with enteric nervous system effects.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. FALSE</strong> &mdash; More opioid usually worsens the pain; management is supervised opioid reduction or withdrawal.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. TRUE</strong> &mdash; Marked worsening of pain as the dose wanes, with improvement when opioids are reinstituted, is a diagnostic feature.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Narcotic Bowel Syndrome</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\">\n    <div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Narcotic bowel syndrome (opioid-induced gastrointestinal hyperalgesia) is a paradoxical condition in which chronic or recurrent abdominal pain persists or worsens despite continued or escalating opioid doses. It is distinct from opioid-induced constipation, and treating it with more opioid makes it worse.</p></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Rome IV diagnostic criteria</div><table style=\"margin:0\"><tr><th>Criterion</th></tr><tr><td>Chronic or frequently recurring abdominal pain treated with acute high-dose or chronic opioids</td></tr><tr><td>The nature and intensity of the pain is not explained by a current or previous gastrointestinal diagnosis</td></tr><tr><td>Two or more of the following:<br>&bull; Pain worsens or incompletely resolves with continued or escalating opioid doses<br>&bull; Marked worsening of pain as the opioid dose wanes, with improvement when opioids are reinstituted<br>&bull; Progression of the frequency, duration and intensity of pain episodes</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">All criteria must be met. The pattern of pain worsening as each dose wears off and easing after the next dose is often described as &ldquo;soar and crash&rdquo;.</p></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical features and mechanisms</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Often diffuse, poorly localised abdominal pain with nausea, vomiting, bloating and constipation; investigations (imaging, endoscopy) are unrevealing</td></tr><tr><td>Thought to reflect opioid-induced hyperalgesia (central sensitisation, including NMDA receptor activation and spinal dynorphin upregulation) together with opioid effects on the enteric nervous system</td></tr><tr><td>Develops on prolonged or high-dose use, most often with opioids prescribed for chronic non-cancer abdominal pain or after abdominal surgery</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Narcotic bowel syndrome versus opioid-induced constipation</div><table style=\"margin:0\"><tr><th>Feature</th><th>Narcotic bowel syndrome</th><th>Opioid-induced constipation</th></tr><tr><td>Main problem</td><td>Abdominal pain that worsens with opioid</td><td>Reduced bowel frequency, straining, incomplete evacuation</td></tr><tr><td>Effect of more opioid</td><td>Pain worsens</td><td>Constipation worsens</td></tr><tr><td>Effect of reducing opioid</td><td>Pain improves once withdrawal settles</td><td>Bowel function improves</td></tr><tr><td>Treatment</td><td>Opioid withdrawal</td><td>Laxatives; peripheral opioid antagonists (e.g. naloxegol, methylnaltrexone)</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Management</div><table style=\"margin:0\"><tr><th>Step</th><th>Approach</th></tr><tr><td>Recognise and explain</td><td>Explain that the opioid is contributing to the pain; agree a plan and avoid further dose escalation</td></tr><tr><td>Withdraw the opioid</td><td>Structured, supervised opioid reduction or withdrawal (specialist or inpatient support for high doses); pain often worsens transiently before improving</td></tr><tr><td>Support during withdrawal</td><td>Adjuncts such as clonidine for autonomic withdrawal symptoms, and neuropathic or visceral pain agents (e.g. tricyclic antidepressants, gabapentinoids)</td></tr><tr><td>Bowel and psychosocial care</td><td>Laxatives for constipation; psychological support, including cognitive behavioural approaches</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Evidence is largely from case series and expert consensus rather than trials.</p></div>\n  </div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_narcotic_bowel_syndrome_management_001', 'SBA', '{"dateAdded":"2026-10-16","rotationIndex":171,"question":"A patient taking high-dose oral morphine for chronic abdominal pain is diagnosed with narcotic bowel syndrome. Which is the most appropriate management?","choices":["Explain the diagnosis and arrange supervised gradual opioid withdrawal","Increase the morphine dose","Rotate to an equianalgesic dose of another strong opioid","Add methylnaltrexone and continue the current opioid","Refer for coeliac plexus neurolysis"],"correct":0,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Treatment centres on recognising the condition, explaining it to the patient and withdrawing the opioid under supervision, with support for withdrawal symptoms, pain and bowel function.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Correct.</strong> Structured, supervised opioid reduction or withdrawal, with explanation and support, is the mainstay of treatment.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> Escalating the dose is expected to worsen the pain.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> Rotating to another opioid keeps the patient on the drug that is driving the hyperalgesia and does not address the underlying problem.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Peripheral opioid antagonists treat opioid-induced constipation; they do not resolve the central hyperalgesia while the opioid continues.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Coeliac plexus neurolysis is used for selected upper abdominal visceral cancer pain and is not a treatment for this condition.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Narcotic Bowel Syndrome</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\">\n    <div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Narcotic bowel syndrome (opioid-induced gastrointestinal hyperalgesia) is a paradoxical condition in which chronic or recurrent abdominal pain persists or worsens despite continued or escalating opioid doses. It is distinct from opioid-induced constipation, and treating it with more opioid makes it worse.</p></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Rome IV diagnostic criteria</div><table style=\"margin:0\"><tr><th>Criterion</th></tr><tr><td>Chronic or frequently recurring abdominal pain treated with acute high-dose or chronic opioids</td></tr><tr><td>The nature and intensity of the pain is not explained by a current or previous gastrointestinal diagnosis</td></tr><tr><td>Two or more of the following:<br>&bull; Pain worsens or incompletely resolves with continued or escalating opioid doses<br>&bull; Marked worsening of pain as the opioid dose wanes, with improvement when opioids are reinstituted<br>&bull; Progression of the frequency, duration and intensity of pain episodes</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">All criteria must be met. The pattern of pain worsening as each dose wears off and easing after the next dose is often described as &ldquo;soar and crash&rdquo;.</p></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Clinical features and mechanisms</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Often diffuse, poorly localised abdominal pain with nausea, vomiting, bloating and constipation; investigations (imaging, endoscopy) are unrevealing</td></tr><tr><td>Thought to reflect opioid-induced hyperalgesia (central sensitisation, including NMDA receptor activation and spinal dynorphin upregulation) together with opioid effects on the enteric nervous system</td></tr><tr><td>Develops on prolonged or high-dose use, most often with opioids prescribed for chronic non-cancer abdominal pain or after abdominal surgery</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Narcotic bowel syndrome versus opioid-induced constipation</div><table style=\"margin:0\"><tr><th>Feature</th><th>Narcotic bowel syndrome</th><th>Opioid-induced constipation</th></tr><tr><td>Main problem</td><td>Abdominal pain that worsens with opioid</td><td>Reduced bowel frequency, straining, incomplete evacuation</td></tr><tr><td>Effect of more opioid</td><td>Pain worsens</td><td>Constipation worsens</td></tr><tr><td>Effect of reducing opioid</td><td>Pain improves once withdrawal settles</td><td>Bowel function improves</td></tr><tr><td>Treatment</td><td>Opioid withdrawal</td><td>Laxatives; peripheral opioid antagonists (e.g. naloxegol, methylnaltrexone)</td></tr></table></div>\n    <div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Management</div><table style=\"margin:0\"><tr><th>Step</th><th>Approach</th></tr><tr><td>Recognise and explain</td><td>Explain that the opioid is contributing to the pain; agree a plan and avoid further dose escalation</td></tr><tr><td>Withdraw the opioid</td><td>Structured, supervised opioid reduction or withdrawal (specialist or inpatient support for high doses); pain often worsens transiently before improving</td></tr><tr><td>Support during withdrawal</td><td>Adjuncts such as clonidine for autonomic withdrawal symptoms, and neuropathic or visceral pain agents (e.g. tricyclic antidepressants, gabapentinoids)</td></tr><tr><td>Bowel and psychosocial care</td><td>Laxatives for constipation; psychological support, including cognitive behavioural approaches</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Evidence is largely from case series and expert consensus rather than trials.</p></div>\n  </div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
